import{_ as e,o,c as p,a5 as r}from"./chunks/framework.DJo0M80U.js";const m=JSON.parse('{"title":"一发入魂","description":"","frontmatter":{"title":"一发入魂","date":"2026-07-03T00:00:00.000Z","categories":["Java 快速入门"],"tags":["Java","附录","OneNote"],"lastUpdated":false},"headers":[],"relativePath":"posts/java快速入门/附录/未分类/一发入魂/一发入魂.md","filePath":"posts/java快速入门/附录/未分类/一发入魂/一发入魂.md"}'),a={name:"posts/java快速入门/附录/未分类/一发入魂/一发入魂.md"};function c(d,t,i,g,n,s){return o(),p("div",null,[...t[0]||(t[0]=[r("<div><p><code>mybatis-plus</code>是一款<code>Mybatis</code>增强工具，用于简化开发，提高效率。 注：本文使用的<code>mp</code>版本是当前最新的<code>3.4.2</code>； 官方网站：<code>baomidou.com/</code></p><p>快速入门 <code>1.</code> 创建一个<code>SpringBoot</code>项目 <code>2.</code> 导入依赖</p><p>&lt;dependency&gt; &lt;groupId&gt;com.baomidou&lt;/groupId&gt; &lt;artifactId&gt;mybatis-plus-boot-starter&lt;/artifactId&gt; &lt;version&gt;3.5.1&lt;/version&gt; &lt;/dependency&gt; 全部依赖： <code>\\&lt;!--spring.boot</code>==相关==</p><p>--&gt; &lt;dependency&gt; &lt;groupId&gt;org.mybatis.spring.boot&lt;/groupId&gt; &lt;artifactId&gt;mybatis-spring-boot-starter&lt;/artifactId&gt; &lt;version&gt;2.2.2&lt;/version&gt; &lt;/dependency&gt; &lt;dependency&gt; &lt;groupId&gt;org.springframework.boot&lt;/groupId&gt; &lt;artifactId&gt;spring-boot-configuration-processor&lt;/artifactId&gt; &lt;optional&gt;true&lt;/optional&gt; &lt;/dependency&gt; &lt;dependency&gt; &lt;groupId&gt;org.springframework.boot&lt;/groupId&gt; &lt;artifactId&gt;spring-boot-devtools&lt;/artifactId&gt; &lt;scope&gt;runtime&lt;/scope&gt; &lt;optional&gt;true&lt;/optional&gt; &lt;/dependency&gt; &lt;dependency&gt; &lt;groupId&gt;org.springframework.boot&lt;/groupId&gt; &lt;artifactId&gt;spring-boot-starter-test&lt;/artifactId&gt; &lt;scope&gt;test&lt;/scope&gt; &lt;/dependency&gt;</p><p>&lt;!--springbootweb--&gt; &lt;dependency&gt; &lt;groupId&gt;org.springframework.boot&lt;/groupId&gt; &lt;artifactId&gt;spring-boot-starter-web&lt;/artifactId&gt; &lt;/dependency&gt; &lt;!--springboot ==数据库==</p><p>--&gt; &lt;dependency&gt; &lt;groupId&gt;org.springframework.boot&lt;/groupId&gt; &lt;artifactId&gt;spring-boot-starter-jdbc&lt;/artifactId&gt; &lt;/dependency&gt; &lt;!--mysql--&gt; &lt;dependency&gt; &lt;groupId&gt;com.mysql&lt;/groupId&gt; &lt;artifactId&gt;mysql-connector-j&lt;/artifactId&gt; &lt;scope&gt;runtime&lt;/scope&gt; &lt;/dependency&gt; &lt;!--lombok--&gt; &lt;dependency&gt; &lt;groupId&gt;org.projectlombok&lt;/groupId&gt; &lt;artifactId&gt;lombok&lt;/artifactId&gt; &lt;optional&gt;true&lt;/optional&gt; &lt;/dependency&gt;</p><p><code>3.</code> 配置数据库</p><p>spring: datasource: driver-class-name: com.mysql.cj.jdbc.Driver url: jdbc:mysql://localhost:3306/yogurt?serverTimezone=Asia/Shanghai username: root password: Hr123456</p><p>mybatis-plus: configuration: # 开启<code>SQL</code>语句打印 <code>log-impl: org.apache.ibatis.logging.stdout.StdOutImpl</code></p><p><code>4.</code> 创建一个实体类</p><p>package com.example.demo. ==po==</p><p>; import lombok.Data; import java.time.LocalDateTime; @Data public class User {</p><p>private Long id;</p><p>private String name;</p><p>private Integer age;</p><p>private String email;</p><p>private Long managerId;</p><p>private LocalDateTime createTime; }</p><p><code>5.</code> 创建一个<code>mapper</code>接口</p><p>package com.example.demo.mapper; import com.baomidou.mybatisplus.core.mapper.BaseMapper; import com.example.demo.entity.User; public interface UserMapper extends BaseMapper&lt;User&gt; { }</p><p><code>6.</code> 在<code>SpringBoot</code>启动类上配置<code>mapper</code>接口的扫描路径</p><p>package com.example.demo; import org.mybatis.spring.annotation.MapperScan; import org.springframework.boot.SpringApplication; import org.springframework.boot.autoconfigure.SpringBootApplication; @SpringBootApplication @MapperScan(&quot;com.example.demo.mappers&quot;) public class Demo1Application {</p><p>public static void main(String[] args) {</p><p>SpringApplication.run(Demo1Application.class, args);</p><p>} }</p><p><code>7.</code> 在数据库中创建表 <code>DROP TABLE IF EXISTS user; CREATE TABLE user ( id BIGINT(20) PRIMARY KEY NOT NULL COMMENT &#39;</code>主键<code>&#39;, name VARCHAR(30) DEFAULT NULL COMMENT &#39;</code>姓名<code>&#39;, age INT(11) DEFAULT NULL COMMENT &#39;</code>年龄<code>&#39;, email VARCHAR(50) DEFAULT NULL COMMENT &#39;</code>邮箱<code>&#39;, manager_id BIGINT(20) DEFAULT NULL COMMENT &#39;</code>直属上级<code>id&#39;, create_time DATETIME DEFAULT NULL COMMENT &#39;</code>创建时间<code>&#39;, CONSTRAINT manager_fk FOREIGN KEY(manager_id) REFERENCES user (id) ) ENGINE=INNODB CHARSET=UTF8;</code></p><p><code>INSERT INTO user(id, name, age ,email, manager_id, create_time) VALUES(1, &#39;</code>大</p><p>BOSS&#39;, 40, &#39;boss@baomidou.com&#39;, NULL, &#39;2021-03-22 09:48:00&#39;), (2, &#39; 李经理</p><p>&#39;, 40, &#39;boss@baomidou.com&#39;, 1, &#39;2021-01-22 09:48:00&#39;), (3, &#39; 黄主管</p><p>&#39;, 40, &#39;boss@baomidou.com&#39;, 2, &#39;2021-01-22 09:48:00&#39;), (4, &#39; 吴组长</p><p>&#39;, 40, &#39;boss@baomidou.com&#39;, 2, &#39;2021-02-22 09:48:00&#39;), (5, &#39; 小菜<code>&#39;, 40, &#39;boss@baomidou.com&#39;, 2, &#39;2021-02-22 09:48:00&#39;)</code></p><p><code>8.</code> 编写一个<code>SpringBoot</code>测试类</p><p>packagecom.example.mp; importcom.example.mp.mappers.UserMapper; importcom.example.mp.po.User; importorg.junit.Test; importorg.junit.runner.RunWith; importorg.springframework.beans.factory.annotation.Autowired; importorg.springframework.boot.test.context.SpringBootTest; importorg.springframework.test.context.junit4.SpringRunner; importjava.util.List; importstaticorg.junit.Assert.*; @RunWith(SpringRunner.class) @SpringBootTest Public class SampleTest{ @Autowired Private UserMapper mapper;</p><p>@Test Public void testSelect(){ List&lt;User&gt; list = mapper.selectList(null); assertEquals(5, list.size()); list.forEach(System.out::println); } } 运行测试类 可以看到，针对单表的基本<code>CRUD</code>操作，只需要创建好实体类，并创建一个继承自<code>BaseMapper</code>的接口即可，可谓非常简洁。并且，我们注意到，<code>User</code>类中的<code>managerId</code>，<code>createTime</code>属性，自动和数据库表中的<code>manager_id</code>，<code>create_time</code>对应了起来，这是因为<code>mp</code>自动做了数据库下划线命名，到<code>Java</code>类的驼峰命名之间的转化。</p></div>",1)])])}const u=e(a,[["render",c]]);export{m as __pageData,u as default};
